import 'package:flutter/material.dart';
import '../../services/mobile_api_service.dart';

class EditSubmissionSlotScreen extends StatefulWidget { const EditSubmissionSlotScreen({super.key, required this.slot}); final Map<String,dynamic> slot; @override State<EditSubmissionSlotScreen> createState()=>_EditSubmissionSlotScreenState(); }
class _EditSubmissionSlotScreenState extends State<EditSubmissionSlotScreen>{late final title=TextEditingController(text:'${widget.slot['title']??''}'), description=TextEditingController(text:'${widget.slot['description']??''}');late DateTime start=DateTime.tryParse('${widget.slot['start_date']}')??DateTime.now(),end=DateTime.tryParse('${widget.slot['end_date']}')??DateTime.now().add(const Duration(days:7));late String status=widget.slot['status']=='closed'?'closed':'open',role=['SK Chairman','SK Secretary','Both'].contains(widget.slot['role'])?'${widget.slot['role']}':'Both';bool saving=false;@override void dispose(){title.dispose();description.dispose();super.dispose();}Future<void> save()async{final id=int.tryParse('${widget.slot['slot_id']}');if(id==null)return;if(title.text.trim().isEmpty||end.isBefore(start)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter a title and valid dates.')));return;}setState(()=>saving=true);try{await MobileApiService.updateSubmissionSlot(slotId:id,title:title.text.trim(),description:description.text.trim(),startDate:start,endDate:end,status:status,role:role);if(mounted)Navigator.pop(context,true);}on MobileApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Edit Submission Slot')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),const SizedBox(height:14),TextField(controller:description,maxLines:3,decoration:const InputDecoration(labelText:'Description')),const SizedBox(height:14),DropdownButtonFormField(initialValue:status,decoration:const InputDecoration(labelText:'Slot status'),items:const[DropdownMenuItem(value:'open',child:Text('Open')),DropdownMenuItem(value:'closed',child:Text('Closed'))],onChanged:(v)=>setState(()=>status=v??status)),const SizedBox(height:14),DropdownButtonFormField(initialValue:role,decoration:const InputDecoration(labelText:'Target role'),items:const[DropdownMenuItem(value:'SK Chairman',child:Text('SK Chairman')),DropdownMenuItem(value:'SK Secretary',child:Text('SK Secretary')),DropdownMenuItem(value:'Both',child:Text('Both'))],onChanged:(v)=>setState(()=>role=v??role)),const SizedBox(height:14),Row(children:[Expanded(child:OutlinedButton(onPressed:()async{final d=await showDatePicker(context:context,initialDate:start,firstDate:DateTime(2020),lastDate:DateTime(2100));if(d!=null)setState(()=>start=d);},child:Text('Start: ${start.year}-${start.month}-${start.day}'))),const SizedBox(width:10),Expanded(child:OutlinedButton(onPressed:()async{final d=await showDatePicker(context:context,initialDate:end,firstDate:start,lastDate:DateTime(2100));if(d!=null)setState(()=>end=d);},child:Text('End: ${end.year}-${end.month}-${end.day}')))]),const SizedBox(height:28),FilledButton(onPressed:saving?null:save,child:Text(saving?'Saving...':'Save Changes'))]));}
